+type Version = [number, number, number];
+type Predicate = (version: Version) => boolean;
+// A possibly partial version: null marks a wildcard or an omitted number.
+type Partial = [number | null, number | null, number | null];
+
+const VERSION = /^\d+\.\d+\.\d+$/;
+const NUMBER = /^\d+$/;
+const WILDCARD = /^[xX*]$/;
+const OPERATORS = [">=", "<=", ">", "<", "=", "~", "^"] as const;
+
+function invalid(text: string): Error {
+  return new Error(`Invalid version or range: ${JSON.stringify(text)}`);
+}
+
+function cmp(a: Version, b: Version): number {
+  return a[0] - b[0] || a[1] - b[1] || a[2] - b[2];
+}
+
+function parseVersion(text: string): Version {
+  if (!VERSION.test(text)) throw invalid(text);
+  const [major, minor, patch] = text.split(".").map(Number);
+  return [major, minor, patch];
+}
+
+function parsePartial(text: string): Partial {
+  const parts = text.split(".");
+  if (parts.length > 3) throw invalid(text);
+  const partial: Partial = [null, null, null];
+  let wildcard = false;
+  for (const [i, part] of parts.entries()) {
+    if (WILDCARD.test(part)) {
+      wildcard = true;
+    } else if (NUMBER.test(part) && !wildcard) {
+      partial[i] = Number(part);
+    } else {
+      throw invalid(text);
+    }
+  }
+  return partial;
+}
+
